css:
@font-face { font-family: 'JBM'; src: url(node_modules/@fontsource/jetbrains-mono/files/jetbrains-mono-latin-500-normal.woff2); font-weight: 500; }
@font-face { font-family: 'JBM'; src: url(node_modules/@fontsource/jetbrains-mono/files/jetbrains-mono-latin-800-normal.woff2); font-weight: 800; }
.card { background: #0B0B0B; color: #C6FF3D; font-family: 'JBM'; }
.card::before { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(0deg, rgba(255,255,255,.035) 0 2px, transparent 2px 6px); }
.bar { position: absolute; top: 120px; left: 80px; right: 140px; height: 70px; border: 3px solid #2E3A12; display: flex; align-items: center; gap: 16px; padding: 0 22px; }
.bar i { width: 22px; height: 22px; border-radius: 50%; background: #FF4B2B; display: block; }
.bar i:nth-child(2) { background: #FFC23D; } .bar i:nth-child(3) { background: #C6FF3D; }
.bar span { font: 500 30px 'JBM'; color: #7E9A3A; margin-left: 12px; }
.prompt { font: 500 52px 'JBM'; color: #7E9A3A; margin: 0 0 36px; }
h1 { font: 800 132px/1.02 'JBM'; letter-spacing: -4px; margin: 0 0 34px; color: #C6FF3D; }
.hot { color: #FF4B2B; }
.tag { align-self: flex-start; background: #C6FF3D; color: #0B0B0B; font: 800 48px 'JBM'; padding: 10px 22px; margin-bottom: 44px; }
p.l { font: 500 60px/1.28 'JBM'; color: #F2F2E8; margin: 0 0 38px; }
p.l::before { content: '> '; color: #C6FF3D; }
.note { align-self: flex-start; border: 5px solid #FF4B2B; color: #FF4B2B; font: 800 56px 'JBM'; padding: 14px 24px; margin-top: 20px; }
.row { display: flex; gap: 26px; align-items: center; border-top: 3px dashed #4A5E1C; padding: 28px 0; font: 800 84px/1.1 'JBM'; color: #F2F2E8; }
.row b { color: #FF4B2B; font-size: 84px; min-width: 120px; }
.cursor { display: inline-block; width: 0.55em; height: 0.9em; background: #C6FF3D; vertical-align: -0.1em; margin-left: 10px; }
.end h1 { font-size: 124px; }
.end .handle { font: 800 60px 'JBM'; color: #0B0B0B; background: #C6FF3D; padding: 16px 26px; align-self: flex-start; margin-top: 30px; }
